import{_ as t,C as d,c as r,o,j as a,b as c,a6 as n,a as i,w as l,G as m,aL as u}from"./chunks/framework.BY05barL.js";const p="/ucasal-ssoo-estudio/assets/12-llamadas-sistema.vXhgCAk2.png",b="/ucasal-ssoo-estudio/assets/12-read.BT86nivH.png",h="/ucasal-ssoo-estudio/assets/20-syscall-librarycall.DQeERD1B.png",y=JSON.parse('{"title":"Llamadas al Sistema","description":"","frontmatter":{},"headers":[],"relativePath":"unidad1/llamadas-sistema.md","filePath":"unidad1/llamadas-sistema.md"}'),f={name:"unidad1/llamadas-sistema.md"};function g(A,e,v,C,q,E){const s=d("Mermaid");return o(),r("div",null,[e[1]||(e[1]=a("h1",{id:"llamadas-al-sistema",tabindex:"-1"},[i("Llamadas al Sistema "),a("a",{class:"header-anchor",href:"#llamadas-al-sistema","aria-label":'Permalink to "Llamadas al Sistema"'},"​")],-1)),e[2]||(e[2]=a("p",null,"Las llamadas al sistema (system calls) son el mecanismo utilizado por un proceso en modo usuario para solicitar un servicio al sistema operativo.",-1)),(o(),c(u,null,{default:l(()=>[m(s,{id:"mermaid-6",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20UA%20as%20User%20application%0A%20%20%20%20participant%20CL%20as%20C-Library%0A%20%20%20%20participant%20K%20as%20Kernel%0A%20%20%20%20participant%20SC%20as%20System%20call%0A%20%20%20%20%0A%20%20%20%20Note%20over%20UA%2C%20CL%3A%20User-space%0A%20%20%20%20Note%20over%20K%2C%20SC%3A%20Kernel-space%0A%20%20%20%20%0A%20%20%20%20UA-%3E%3ECL%3A%20link(const%20char%2C%20const%20char)%0A%20%20%20%20CL-%3E%3EK%3A%20Load%20arguments%3Cbr%2F%3Eeax%20%3D%20__NR_link%3Cbr%2F%3Etransition%20to%20kernel%20(int%2080)%0A%20%20%20%20K-%3E%3ESC%3A%20system_call%0A%20%20%20%20SC-%3E%3ESC%3A%20call%3Cbr%2F%3Esystem_call_table%5Beax%5D%0A%20%20%20%20SC-%3E%3EK%3A%20sys_link()%0A%20%20%20%20K-%3E%3ESC%3A%20return%0A%20%20%20%20SC-%3E%3ECL%3A%20syscall_exit%3Cbr%2F%3Eresume%20userspace%0A%20%20%20%20CL-%3E%3EUA%3A%20Return%0A%20%20%20%20%0A%20%20%20%20rect%20rgb(255%2C%20255%2C%20200)%0A%20%20%20%20%20%20%20%20Note%20right%20of%20UA%3A%20User-space%20execution%0A%20%20%20%20end%0A%20%20%20%20%0A%20%20%20%20rect%20rgb(200%2C%20255%2C%20200)%0A%20%20%20%20%20%20%20%20Note%20right%20of%20K%3A%20Kernel-space%20execution%0A%20%20%20%20end%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=n('<h2 id="caracteristicas-principales" tabindex="-1">Características principales <a class="header-anchor" href="#caracteristicas-principales" aria-label="Permalink to &quot;Características principales&quot;">​</a></h2><ul><li>Las llamadas al sistema son instrucciones de lenguaje de máquina</li><li>Se ejecutan en modo kernel</li><li>Permiten que los procesos realicen tareas restringidas</li><li>Ejecutan la instrucción <code>TRAP</code></li><li>Las llamadas al sistema son la interfaz entre el modo usuario y el modo kernel</li></ul><p><img src="'+p+'" alt="Llamadas al sistema"></p><h2 id="funcionamiento" tabindex="-1">Funcionamiento <a class="header-anchor" href="#funcionamiento" aria-label="Permalink to &quot;Funcionamiento&quot;">​</a></h2><p>Cuando un programa necesita realizar una operación que requiere privilegios de kernel (como acceder a hardware o a recursos protegidos), debe realizar una llamada al sistema:</p><ol><li>El programa prepara los parámetros para la llamada al sistema</li><li>El programa ejecuta una instrucción especial (TRAP) que cambia el modo de ejecución de usuario a kernel</li><li>El sistema operativo verifica la validez de la solicitud</li><li>El sistema operativo ejecuta el servicio solicitado</li><li>El sistema operativo devuelve el control al programa en modo usuario</li></ol><h2 id="ejemplo-llamada-al-sistema-read-fd-buffer-nbytes" tabindex="-1">Ejemplo: Llamada al sistema <code>read(fd, buffer, nbytes)</code> <a class="header-anchor" href="#ejemplo-llamada-al-sistema-read-fd-buffer-nbytes" aria-label="Permalink to &quot;Ejemplo: Llamada al sistema `read(fd, buffer, nbytes)`&quot;">​</a></h2><p>La llamada al sistema <code>read()</code> permite a un programa leer datos de un archivo o dispositivo:</p><ul><li><code>fd</code>: Descriptor de archivo</li><li><code>buffer</code>: Buffer de lectura</li><li><code>nbytes</code>: Número de bytes a leer</li></ul><p><img src="'+b+'" alt="Llamada al sistema read()"></p><h2 id="llamadas-al-sistema-vs-procedimientos-de-biblioteca" tabindex="-1">Llamadas al sistema vs. Procedimientos de biblioteca <a class="header-anchor" href="#llamadas-al-sistema-vs-procedimientos-de-biblioteca" aria-label="Permalink to &quot;Llamadas al sistema vs. Procedimientos de biblioteca&quot;">​</a></h2><h3 id="llamada-al-sistema" tabindex="-1">Llamada al Sistema <a class="header-anchor" href="#llamada-al-sistema" aria-label="Permalink to &quot;Llamada al Sistema&quot;">​</a></h3><ul><li>Son costosas en términos de tiempo</li><li>Se ejecutan en modo kernel</li><li>Varían según el SO</li></ul><h3 id="procedimiento-de-biblioteca" tabindex="-1">Procedimiento de Biblioteca <a class="header-anchor" href="#procedimiento-de-biblioteca" aria-label="Permalink to &quot;Procedimiento de Biblioteca&quot;">​</a></h3><ul><li>Es una función definida por una librería</li><li>Se ejecutan en modo usuario</li><li>Son independientes del SO</li></ul><p><img src="'+h+'" alt="Llamada al Sistema y Procedimiento de Biblioteca"></p><h3 id="¿una-llamada-al-sistema-se-ve-distinta-de-un-procedimiento-de-biblioteca" tabindex="-1">¿Una llamada al sistema se ve distinta de un procedimiento de biblioteca? <a class="header-anchor" href="#¿una-llamada-al-sistema-se-ve-distinta-de-un-procedimiento-de-biblioteca" aria-label="Permalink to &quot;¿Una llamada al sistema se ve distinta de un procedimiento de biblioteca?&quot;">​</a></h3><p><strong>Se ven iguales.</strong> En C, <code>read(fd, buffer, nbytes)</code> se escribe igual que <code>strlen(s)</code>: es una llamada a una función. La diferencia está adentro: <code>read()</code> es un procedimiento de biblioteca que prepara los parámetros y ejecuta <code>TRAP</code> para pasar a modo kernel, mientras que <code>strlen()</code> se resuelve completa en modo usuario.</p><h3 id="importancia-de-saber-distinguir-entre-llamadas-al-sistema-y-procedimientos-de-biblioteca" tabindex="-1">Importancia de saber distinguir entre llamadas al sistema y procedimientos de biblioteca: <a class="header-anchor" href="#importancia-de-saber-distinguir-entre-llamadas-al-sistema-y-procedimientos-de-biblioteca" aria-label="Permalink to &quot;Importancia de saber distinguir entre llamadas al sistema y procedimientos de biblioteca:&quot;">​</a></h3><ul><li><strong>Rendimiento</strong>: cada llamada al sistema es mucho más costosa que una llamada común. Hay que cambiar de modo usuario a kernel, guardar el contexto, validar la solicitud y volver. Además, al terminar la llamada, el SO puede elegir ejecutar otro proceso, lo que retrasa todavía más al que la hizo.</li><li><strong>Bloqueo</strong>: una llamada al sistema puede bloquear al proceso (por ejemplo, <code>read()</code> esperando datos del teclado o del disco).</li><li><strong>Portabilidad</strong>: las llamadas al sistema cambian según el SO. Las funciones de biblioteca estándar (como <code>fopen()</code>) son iguales en todos.</li></ul><p>Ejemplo: escribir un archivo de a un byte con <code>write()</code> hace una llamada al sistema por cada byte. Con <code>fwrite()</code> o <code>putc()</code>, la biblioteca junta los datos en un búfer y llama a <code>write()</code> pocas veces. El archivo queda igual, pero el programa es mucho más rápido.</p><table tabindex="0"><thead><tr><th>Función</th><th>¿Hace una llamada al sistema?</th></tr></thead><tbody><tr><td><code>strlen()</code>, <code>strcpy()</code>, <code>sqrt()</code></td><td>No</td></tr><tr><td><code>printf()</code>, <code>fwrite()</code></td><td>A veces: cuando se llena el búfer, llaman a <code>write()</code></td></tr><tr><td><code>malloc()</code>, <code>free()</code></td><td>A veces: cuando necesitan más memoria, llaman a <code>brk()</code> o <code>mmap()</code></td></tr><tr><td><code>read()</code>, <code>write()</code>, <code>fork()</code></td><td>Sí: son envoltorios directos de la llamada al sistema</td></tr></tbody></table><h2 id="ejemplos-comunes-de-llamadas-al-sistema" tabindex="-1">Ejemplos comunes de llamadas al sistema <a class="header-anchor" href="#ejemplos-comunes-de-llamadas-al-sistema" aria-label="Permalink to &quot;Ejemplos comunes de llamadas al sistema&quot;">​</a></h2><ul><li><strong>Gestión de procesos</strong>: <code>fork()</code>, <code>exec()</code>, <code>exit()</code>, <code>wait()</code></li><li><strong>Gestión de archivos</strong>: <code>open()</code>, <code>close()</code>, <code>read()</code>, <code>write()</code></li><li><strong>Gestión de directorios</strong>: <code>mkdir()</code>, <code>rmdir()</code>, <code>link()</code>, <code>unlink()</code></li><li><strong>Gestión de memoria</strong>: <code>brk()</code>, <code>mmap()</code>, <code>munmap()</code></li><li><strong>Comunicación</strong>: <code>pipe()</code>, <code>socket()</code>, <code>connect()</code>, <code>accept()</code></li></ul><h2 id="mejoras-de-performance-relacionadas-a-system-calls" tabindex="-1">Mejoras de performance relacionadas a System Calls <a class="header-anchor" href="#mejoras-de-performance-relacionadas-a-system-calls" aria-label="Permalink to &quot;Mejoras de performance relacionadas a System Calls&quot;">​</a></h2><p><a href="https://bun.com/blog/behind-the-scenes-of-bun-install" target="_blank" rel="noreferrer">https://bun.com/blog/behind-the-scenes-of-bun-install</a></p>',26))])}const S=t(f,[["render",g]]);export{y as __pageData,S as default};
